grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc)
  Root ::= F(COMMIT('a')) 'x' ;
  F(x) ::= { x } ;
}

grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc)
  Root ::= CATCH({ COMMIT('a') }, 'b', L) ;
  Z ::= LABEL(L, 'z') LABEL(M, 'z') ;
}

grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc)
  Root ::= CATCH({ LABEL(M, 'a') }, 'b', L) ;
  Z ::= LABEL(L, 'z') LABEL(M, 'z') ;
