}

grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc, params=[s])
  Root ::= { Statement @s } ;
  @recovery(sync=';')
  Statement ::= { LABEL(L, 'a') } ';' ;
  Z ::= LABEL(L, 'z') ;
}

grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc, params=[s])
  Root ::= { Statement @s } ;
  @recovery(sync=';')
  Statement ::= { COMMIT('a', 'need a') } ';' ;
}

grammar Cut {
  @package: cutprobe
  @whitespace: none
  @root @mapping(Doc, params=[s])
  Root ::= { Statement @s } ;
  @recovery(sync=';')
  Statement ::= Item ';' ;
  Item ::= { COMMIT('a', 'need a') } ;
}
